import numpy as np
from scipy.optimize import curve_fit
lam=1.5406
def g(x,A,mu,sig,b0,b1):
    return A*np.exp(-0.5*((x-mu)/sig)**2)+b0+b1*(x-mu)
ids=['m1','m2']
pts=[]
for mid in ids:
    m=meas[mid]; x=np.asarray(m['two_theta']); y=np.asarray(m['counts'],float)
    pts.append((mid,x,y))
# candidate centers (ref, label)
a0,c0=4.5937,2.9587
def tt(h,k,l,a,c):
    inv2=(h*h+k*k)/a**2+l*l/c**2
    return 2*np.degrees(np.arcsin(lam/2*np.sqrt(inv2)))
cands=[]
for h,k,l in [(1,1,0),(0,0,1),(1,0,1),(2,0,0),(1,1,1),(2,1,0),(2,0,1),(2,1,1),(2,2,0),(3,0,0),(0,0,2),(3,1,0),(2,2,1),(1,0,2),(3,0,1),(1,1,2),(3,1,1),(3,2,0),(2,0,2),(2,1,2),(3,2,1),(4,0,0),(4,1,0),(2,2,2),(3,3,0),(4,0,1),(3,0,2),(4,1,1),(3,1,2),(4,2,0),(3,3,1)]:
    cands.append(('R%d%d%d'%(h,k,l), tt(h,k,l,a0,c0)))
asi=5.43102
for h,k,l in [(1,1,1),(2,2,0),(3,1,1),(4,0,0),(3,3,1),(4,2,2),(5,1,1),(4,4,0),(5,3,1),(6,2,0)]:
    cands.append(('S%d%d%d'%(h,k,l), 2*np.degrees(np.arcsin(lam/2*np.sqrt((h*h+k*k+l*l)/asi**2)))))
res=[]
for lab,t0 in cands:
    for mid,x,y in pts:
        w=(x>t0-0.3)&(x<t0+0.3)
        if w.sum()<20: continue
        xx=x[w]; yy=y[w]
        try:
            p,cov=curve_fit(g,xx,yy,p0=[max(yy.max()-yy.min(),1),xx[np.argmax(yy)],0.04,yy.min(),0],maxfev=5000)
        except Exception as e:
            continue
        if p[0]<3: continue
        err=np.sqrt(np.diag(cov))
        if not (t0-0.25<p[1]<t0+0.25): continue
        # Poisson-weighted would be better; simple
        res.append((lab,round(t0,3),mid,round(p[1],4),round(err[1],4),round(p[0],1),round(abs(p[2]),3)))
for r in res: print(r)

